/* REACTION ARROW — a grid, because the notation is two-dimensional.
   The three rows are reagent / arrow / condition. `inline-grid` keeps the
   whole thing on the equation's baseline while letting the labels sit off
   it, which is the one thing a linear run of text cannot do. */
.rxn { display:inline-grid; grid-template-rows:auto auto auto;
       align-items:center; justify-items:center; vertical-align:middle;
       margin:0 5px; min-width:44px; }

/* The arrow is DRAWN, not set as a glyph, so it stretches to whichever
   label is wider. A six-word reagent over a fixed-width `⟶` overhung it on
   both sides and stopped reading as attached to it. */
.rxn>.rxn-a { position:relative; width:100%; height:0;
              border-top:1.4px solid currentColor; margin:2px 0; }
.rxn>.rxn-a::after { content:''; position:absolute; right:-1px; top:-4px;
       border-left:7px solid currentColor; border-top:4px solid transparent;
       border-bottom:4px solid transparent; }

/* Reverse and equilibrium arrows. An equilibrium is two half-arrows,
   which is not the same statement as one arrow with a barb at each end —
   `⇌` means the reaction runs both ways at once, `↔` is resonance.

   NAMED `rxn-harpoon`, NOT `rxn-eq`. The whole-equation wrapper is ALSO
   `.rxn-eq` (`display:inline-flex`, laying reactant/arrow/product side by
   side) — see `.rxn-eq` in acols.rules.json. An equilibrium ARROW used to
   carry that same class name as its kind modifier, so it matched its own
   wrapper's selector too: `display:inline-flex` overrode `.rxn`'s own
   `display:inline-grid`, collapsing the label/arrow/label rows into one
   flex line. The label above the arrow (a slow-step tag such as `मन्द`)
   sat inline before the glyph instead of stacked over it — measured on the
   built page: `.rxn.rxn-eq` computed to `display:flex`, where every other
   arrow kind computed to `display:grid`. Renamed so the arrow's own class
   can never collide with the wrapper's. */
.rxn-back>.rxn-a::after { right:auto; left:-1px;
       border-left:0; border-right:7px solid currentColor; }
.rxn-harpoon>.rxn-a { border-top:0; height:auto; }
.rxn-harpoon>.rxn-a::after { content:'\21cc'; position:static; border:0;
       font-size:1.15em; line-height:1; }
.rxn-both>.rxn-a::after { content:'\27f7'; position:static; border:0;
       font-size:1.05em; line-height:1; }

/* The NAME under a species — prose face, and IN FLOW.
   Unlike a number, a name (`1-ब्रोमोप्रोपेन`) is wider than the
   formula it labels, so its width has to be reserved or it would
   overlap the next species. Row 2, which leaves row 1 — the atom —
   as the grid's baseline row. */
.sp>.sp-u { grid-row:2; font-size:.72em; line-height:1.2;
      font-style:normal; font-family:inherit; text-align:center;
      opacity:.86; padding-top:1px; }

/* A NUMBER OR CHARGE OVER AN ATOM — anchored, not floating.
   Absolutely positioned against the atom's own box and centred on
   it, so it cannot drift and takes no part in the line's layout.
   `CH₃⁺` is a different species from `CH₃`, and a `+` that has
   drifted a line up reads as a separate term in the equation. */
.sp>.sp-o { position:absolute; left:50%; bottom:100%;
      transform:translateX(-50%); font-size:.66em; line-height:1;
      font-weight:600; white-space:nowrap; }

/* A BOND drawn under an atom. The chapter writes a substituent hanging
   below a chain as `\underset{\displaystyle |}{NH}`; that pipe IS a bond
   line, so it is drawn as one rather than left as punctuation. */
.sp>.sp-u:only-child, .sp>.sp-u { }
.sp .bond, .sp>.sp-u:has(>.bond) { font-family:inherit; }

/* `\overline{O}H` — the bar marking a lone pair or a charge. The generic
   converter drops overlines as decoration; in chemistry it distinguishes
   the hydroxide ION from the atom, so it is drawn. */
.ovl { text-decoration:overline; text-decoration-thickness:1.2px;
       text-underline-offset:2px; }

/* A reaction must never run off the sheet. A three-species equation with
   named reactants is wider than a 440px column, and the page is
   `overflow:hidden` — the right-hand side was simply cut off in print with
   no error, because the page's scrollHeight never grew. Wrapping at the `+`
   keeps every species on the paper. */
.dm .rxn, .dm .sp { max-width:100%; }
.subj-chemistry .dm { overflow-wrap:break-word; }
